'use strict';
window.organizerModule=(()=>{
const b=(t,a,c='text-action')=>`<button class="${c}" data-action="${a}">${t}</button>`;
const section=(t,body)=>`<section class="work-section"><h3>${t}</h3>${body}</section>`;
function data(){return {d:deliverablesModule.snapshot(),g:deliveryModule.snapshot(),pending:current().messages.some(m=>m.permission==='pending')}}
function next(){const {d,g,pending}=data();if(!g.goal)return {title:'留在这段对话里',text:'这里没有待执行的工作。需要时，再留下知识点或资料。',action:'ws-context:'+activeId,label:'查看会话上下文'};if(pending)return {title:'先确认保存草案',text:'草案仍在对话中。保存、后续检查与交付等待你的决定。',action:'mg-activity:attention',label:'查看保存请求',wait:true};if(d.review?.findings.some(f=>f.severity==='重要'&&!f.resolved))return {title:'处理 1 项重要审阅发现',text:'输入法候选确认的边界需要复核，之后再给出审阅结论。',action:'dk-panel:审阅',label:'去审阅'};if(g.goal.status!=='done')return {title:g.goal.paused?'检查已暂停':g.goal.status==='running'?'正在检查边界':'继续未完成的检查',text:'已有产物保留，只恢复这一项，不重做整个流程。',action:'dk-panel:进度',label:'查看执行步骤'};return {title:'核对交付条件',text:'自动条件来自实际演示状态，最终结果仍由你确认。',action:'dk-panel:目标',label:'查看验收条件'}}
function overview(){const {d,g}=data(),n=next();return `<div class="work-next"><span class="work-kicker">${n.wait?'需要你决定':'当前下一步'}</span><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p>${b(n.label,n.action,n.wait?'secondary':'primary')}</div>${g.goal?section('这项工作',`<p class="work-objective">${esc(g.goal.objective)}</p><div class="work-fact"><span>交付条件</span><strong>${g.criteria.filter(x=>x.done).length} / ${g.criteria.length}</strong></div>`):''}${section('工作内容',`<div class="work-links">${[['产物',d.artifactCount+' 份'],['审阅',d.review?d.openFindings+' 项待处理':'无变更'],['进度',g.goal?g.completed+'/'+g.steps.length+' 步':'无任务'],['目标',g.goal?'范围与验收':'未设目标']].map(([t,count])=>`<button data-action="dk-panel:${t}"><span>${t}</span><small>${count}</small>${svg('chevron')}</button>`).join('')}</div>`)}`}
function review(inCanvas){const {d}=data(),r=d.review;if(!r)return `<div class="work-empty"><h2>没有代码变更</h2><p>这段对话不是代码工作，不为它建立审阅任务。</p>${b('查看会话配置','dk-panel:会话配置')}</div>`;const f=r.files[r.file];return `<div class="work-status"><strong>${r.status}</strong><span>${r.files.length} 文件 · ${d.openFindings} 发现待处理</span></div>${section('变更文件',r.files.map((f,i)=>`<button class="work-row ${i===r.file?'selected':''}" data-action="rv-file:${i}"><span>${esc(f.name)}</span><small>+${f.added} −${f.removed}</small></button>`).join(''))}${section('选中差异',`<h4>${esc(f.hunks[r.hunk].title)}</h4><pre class="work-diff">${esc(f.hunks[r.hunk].code)}</pre>${b('在标签页打开 '+esc(f.name),'rv-open-review','primary')}`)}${section('审阅发现',r.findings.map(x=>`<button class="work-finding" data-action="rv-locate:${x.id}"><span class="work-severity">${esc(x.severity)}</span><span>${esc(x.title)}<small>${x.resolved?'已解决':'待处理'}</small></span>${svg('chevron')}</button>`).join(''))}`}
function artifacts(inCanvas){return deliverablesModule.panel('产物')}
function progress(inCanvas){const {g,pending}=data();if(!g.goal)return deliveryModule.panel('进度');return `<div class="work-status"><strong>${g.completed}/${g.steps.length} 步完成</strong><span>${esc(g.goal.milestone)}</span></div>${section('执行顺序',g.steps.map((s,i)=>`<button class="work-step" data-action="gp-detail:${s.id}"><span class="work-number">${s.state==='已完成'?'✓':i+1}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.dep)}</small></span><em>${esc(s.state)}</em></button>`).join(''))}${inCanvas?'<p class="work-note">执行记录已打开。选择步骤可查看依赖。</p>':`<div class="work-next compact"><span class="work-kicker">${pending?'等待确认':'当前步骤'}</span><h3>${pending?'保存请求尚未处理':g.goal.paused?'检查已暂停':g.goal.status==='running'?'检查进行中':g.goal.status==='done'?'检查已完成':'检查中断，已有结果保留'}</h3>${b(pending?'查看保存请求':g.goal.status==='running'?(g.goal.paused?'继续演示':'暂停演示'):g.goal.status==='done'?'重新演示失败与恢复':'重试检查',pending?'mg-activity:attention':g.goal.status==='running'?(g.goal.paused?'gp-resume':'gp-pause'):g.goal.status==='done'?'gp-reset':'gp-run','primary')}</div>${b('展开步骤与日志','gp-canvas')}`}`}
function goals(inCanvas){const {g}=data();if(!g.goal)return deliveryModule.panel('目标');return `<div class="work-status"><strong>交付目标</strong><span>${esc(g.goal.priority)}优先级</span></div><h2 class="work-goal">${esc(g.goal.objective)}</h2>${!inCanvas?`<p class="work-scope">${esc(g.goal.scope)}</p>${b('编辑目标与范围','gp-edit')}`:''}${section('成功条件 · '+g.criteria.filter(x=>x.done).length+'/'+g.criteria.length,g.criteria.map(c=>`<button class="work-criterion" data-action="${c.action}"><span>${c.done?'✓':'○'}</span><span>${esc(c.name)}</span>${svg('chevron')}</button>`).join(''))}<div class="work-milestone"><span class="meta">里程碑</span><p>${esc(g.goal.milestone)}</p></div>`}
function canvas(){const {g,pending}=data();if(!g.goal)return `<div class="studio-document">${deliveryModule.panel('进度')}</div>`;return `<div class="studio-document"><div class="eyebrow">执行详情 · 本地演示</div><h1>${esc(g.goal.milestone)}</h1><p class="muted" style="margin-top:12px">输入：目标范围与来源产物。输出：边界检查记录，不运行真实项目测试。</p><div class="action-wrap">${b('查看验收条件','dk-panel:目标')}</div><div class="section-heading"><h2>完整执行日志</h2><span class="meta">${g.goal.logs.length} 条</span></div>${g.goal.logs.map(l=>`<div class="work-log">${esc(l)}</div>`).join('')}<div class="work-next compact" style="margin-top:24px"><h3>${pending?'等待保存授权':g.goal.paused?'执行已暂停':g.goal.status==='done'?'演示检查已完成':'执行与恢复'}</h3>${b(pending?'查看保存请求':g.goal.status==='running'?(g.goal.paused?'继续演示':'暂停演示'):g.goal.status==='done'?'重新演示失败与恢复':'重试检查',pending?'mg-activity:attention':g.goal.status==='running'?(g.goal.paused?'gp-resume':'gp-pause'):g.goal.status==='done'?'gp-reset':'gp-run','primary')}</div><p class="demo-banner">右侧选择步骤可查看输入、输出和依赖。</p></div>`}
return {canvas,panel:(name,canvas)=>name==='工作概览'?overview():name==='审阅'?review(canvas==='review'):name==='产物'?artifacts(canvas==='artifact'):name==='进度'?progress(canvas==='progress'):name==='目标'?goals(canvas==='progress'):null,next};
})();
